/* portrait-data.js
 * The cover portrait as data. Written by execution/mangafy_portrait.py from
 * the photo in sources/portrait. Do not edit by hand: run the script again.
 *
 * tone   how much ink the dot screen lays down: a base64 string of w * h
 *        bytes, row by row. 0 = bare paper, 255 = solid ink.
 * The rest places things around the head. x and y run 0 to 1 across and
 * down the picture. Radii are fractions of its width.
 *   faceX, faceY        the middle of the face
 *   axisX, eyeY         the centre line of the face and the line of the eyes
 *   sunX, sunY, sunR    the disc behind the head
 */
(function (root) {
  'use strict';
  var LJ = (root.LJ = root.LJ || {});
  LJ.portrait = {
    w: 150,
    h: 150,
    faceX: 0.491,
    faceY: 0.463,
    axisX: 0.497,
    eyeY: 0.392,
    sunX: 0.497,
    sunY: 0.336,
    sunR: 0.313,
    tone: ''
  };
})(typeof window !== 'undefined' ? window : globalThis);
